package ncasa.expense.application.occurrence;
import java.time.*;import ncasa.expense.application.port.out.*;
public final class DispatchOutboxMessagesUseCase{private final OutboxMessageRepository messages;private final DomainEventPublisherPort publisher;private final Clock clock;private final int batchSize,maxAttempts;public DispatchOutboxMessagesUseCase(OutboxMessageRepository m,DomainEventPublisherPort p,Clock c,int batch,int max){messages=m;publisher=p;clock=c;batchSize=batch;maxAttempts=max;}public void execute(){for(var message:messages.claim(clock.instant(),batchSize)){try{publisher.publish(message);messages.published(message.id(),clock.instant());}catch(RuntimeException ex){int attempt=message.attempts();long seconds=Math.min(3600L,1L<<Math.min(attempt,12));messages.retry(message.id(),clock.instant().plusSeconds(seconds),safe(ex),attempt>=maxAttempts);}}}private String safe(Exception ex){String value=ex.getClass().getSimpleName();return value.length()>1000?value.substring(0,1000):value;}}
